import { useEffect, useState } from 'react';
import {
  JxToggle,
  JxSlider,
  JxSwitch,
  JxDivider,
  JxSelect,
  JxBadge,
} from '@jinx-ui/react';

interface AppearanceSettings {
  theme: 'light' | 'dark' | 'system';
  scale: number;
  dense: boolean;
  font: string;
}

interface AppearanceSettingsScreenProps {
  defaultTheme?: AppearanceSettings['theme'];
  defaultScale?: number;
  defaultDense?: boolean;
  defaultFont?: string;
  onChange?: (settings: AppearanceSettings) => void;
}

const themeLabels: Record<AppearanceSettings['theme'], string> = {
  light: 'Светлая',
  dark: 'Тёмная',
  system: 'Системная',
};

export default function AppearanceSettingsScreen({
  defaultTheme = 'system',
  defaultScale = 100,
  defaultDense = false,
  defaultFont = 'sans',
  onChange,
}: AppearanceSettingsScreenProps) {
  const [theme, setTheme] = useState<AppearanceSettings['theme']>(defaultTheme);
  const [scale, setScale] = useState(defaultScale);
  const [dense, setDense] = useState(defaultDense);
  const [font, setFont] = useState(defaultFont);

  useEffect(() => {
    onChange?.({ theme, scale, dense, font });
  }, [theme, scale, dense, font, onChange]);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '20px', maxWidth: '480px' }}>
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: '12px',
        }}
      >
        <h2
          style={{
            margin: 0,
            fontFamily: 'var(--jx-font-display)',
            color: 'var(--jx-text)',
          }}
        >
          Внешний вид
        </h2>
        <JxBadge tone="accent">{themeLabels[theme]}</JxBadge>
      </div>

      <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
        <span style={{ color: 'var(--jx-text-2)', fontSize: '14px' }}>Тема</span>
        <JxToggle
          items={[
            { value: 'light', label: 'Светлая' },
            { value: 'dark', label: 'Тёмная' },
            { value: 'system', label: 'Системная' },
          ]}
          value={theme}
          onValueChange={(value) => setTheme(value as AppearanceSettings['theme'])}
        />
      </div>

      <JxSlider
        label="Масштаб интерфейса"
        min={80}
        max={140}
        step={5}
        unit="%"
        showOutput
        value={scale}
        onValueChange={setScale}
      />

      <JxSwitch
        label="Плотная вёрстка"
        checked={dense}
        onChange={(event) => setDense(event.target.checked)}
      />

      <JxDivider label="Ещё" />

      <JxSelect
        label="Шрифт интерфейса"
        options={[
          { value: 'sans', label: 'Inter Tight (по умолчанию)' },
          { value: 'display', label: 'Fraunces' },
          { value: 'mono', label: 'JetBrains Mono' },
        ]}
        value={font}
        onValueChange={setFont}
      />
    </div>
  );
}

